// swift-tools-version: 6.0
// MixAI Decks Rust core for Apple platforms (WP19-15, ADR-0014 D61).
// DecksFFI.xcframework (static libdecks_ffi.a + C header/module map) and Sources/DecksFFI/DecksFFI.swift are
// GENERATED by apps/ios/scripts/build-decks-xcframework.sh and gitignored; only this manifest is committed.
// The package is referenced by the shared XcodeGen project, so it must resolve for the other apps' builds too:
// without the generated xcframework it declares no binary target (the module then holds only the placeholder).
import Foundation
import PackageDescription

let hasBinary = FileManager.default.fileExists(atPath: Context.packageDirectory + "/DecksFFI.xcframework")

let package = Package(
    name: "DecksFFI",
    platforms: [
        .iOS("26.0"),
        .macOS(.v15),
    ],
    products: [
        .library(name: "DecksFFI", targets: ["DecksFFI"]),
    ],
    targets: [
        .target(
            name: "DecksFFI",
            dependencies: hasBinary ? ["decks_ffiFFI"] : [],
            path: "Sources/DecksFFI",
            linkerSettings: [
                // Native deps of the Rust staticlib: wgpu (Metal), cpal (CoreAudio), signalsmith-stretch (C++),
                // bundled SQLite, std (Security for getrandom fallbacks, SystemConfiguration-free).
                .linkedLibrary("c++"),
                .linkedLibrary("resolv"),
                .linkedFramework("Foundation"),
                .linkedFramework("CoreFoundation"),
                .linkedFramework("Metal"),
                .linkedFramework("QuartzCore"),
                .linkedFramework("CoreGraphics"),
                .linkedFramework("CoreAudio"),
                .linkedFramework("AudioToolbox"),
                .linkedFramework("AVFoundation"),
                .linkedFramework("Security"),
                .linkedFramework("IOKit", .when(platforms: [.macOS])),
                .linkedFramework("AudioUnit", .when(platforms: [.macOS])),
                .linkedFramework("AppKit", .when(platforms: [.macOS])),
                .linkedFramework("UIKit", .when(platforms: [.iOS])),
            ]
        ),
    ] + (hasBinary ? [.binaryTarget(name: "decks_ffiFFI", path: "DecksFFI.xcframework")] : []),
    // UniFFI-generated Swift keeps a few process-wide globals; compile it in Swift 5 mode.
    swiftLanguageModes: [.v5]
)
